// Lead Scoring System for BR Academy
const leads = $input.all();
const scoredLeads = [];

for (const lead of leads) {
  const data = lead.json;
  let score = 0;
  let qualificationNotes = [];

  // --- CONTACT INFO SCORING ---
  if (data.phone && data.phone.trim() !== '') {
    score += 15;
    qualificationNotes.push('+15 phone provided');
  }
  if (data.email && data.email.trim() !== '') {
    score += 10;
    qualificationNotes.push('+10 email provided');
  }

  // --- SOURCE SCORING ---
  const sourceScores = {
    'referral': 25,
    'website': 15,
    'whatsapp': 20,
    'instagram': 10,
    'facebook': 10
  };
  const srcScore = sourceScores[data.source] || 5;
  score += srcScore;
  qualificationNotes.push(`+${srcScore} source: ${data.source}`);

  // --- PROFILE COMPLETENESS ---
  if (data.nationality && data.nationality.trim() !== '') {
    score += 5;
    qualificationNotes.push('+5 nationality provided');
  }
  if (data.visa_type && data.visa_type.trim() !== '') {
    score += 10;
    qualificationNotes.push('+10 visa type provided');
  }
  if (data.english_level && data.english_level.trim() !== '') {
    score += 5;
    qualificationNotes.push('+5 english level provided');
  }
  if (data.preferred_date && data.preferred_date.trim() !== '') {
    score += 15;
    qualificationNotes.push('+15 preferred date (high intent)');
  }

  // --- INTENT KEYWORDS IN NOTES ---
  const notes = (data.notes || '').toLowerCase();
  const highIntentWords = ['matricula', 'inscrever', 'pagar', 'pagamento', 'quero', 'enroll', 'register', 'pay', 'start', 'comecar'];
  const medIntentWords = ['preco', 'valor', 'quanto', 'price', 'cost', 'date', 'data', 'quando', 'when'];

  if (highIntentWords.some(w => notes.includes(w))) {
    score += 20;
    qualificationNotes.push('+20 high intent keywords');
  } else if (medIntentWords.some(w => notes.includes(w))) {
    score += 10;
    qualificationNotes.push('+10 medium intent keywords');
  }

  // --- DETERMINE STAGE ---
  let newStage = 'new_lead';
  let priority = 'low';

  if (score >= 70) {
    newStage = 'qualified';
    priority = 'high';
  } else if (score >= 40) {
    newStage = 'contacted';
    priority = 'medium';
  }

  scoredLeads.push({
    json: {
      ...data,
      score: score,
      stage: newStage,
      priority: priority,
      qualification_notes: qualificationNotes.join(' | '),
      updated_at: new Date().toISOString()
    }
  });
}

return scoredLeads;

