// Identify stale leads that need follow-up
const leads = $input.all();
const now = new Date();
const staleLeads = [];

const staleThresholds = {
  'new_lead': 24,       // 24 hours
  'contacted': 48,      // 48 hours
  'qualified': 24,      // 24 hours
  'proposal_sent': 72,  // 72 hours
  'negotiation': 48     // 48 hours
};

for (const lead of leads) {
  const data = lead.json;
  const stage = data.stage;
  const threshold = staleThresholds[stage];

  if (!threshold) continue; // Skip enrolled, in_course, etc.
  if (stage === 'lost') continue;

  const updatedAt = new Date(data.updated_at);
  const hoursSinceUpdate = (now - updatedAt) / (1000 * 60 * 60);

  if (hoursSinceUpdate >= threshold) {
    staleLeads.push({
      json: {
        ...data,
        hours_stale: Math.round(hoursSinceUpdate),
        threshold_hours: threshold,
        action_needed: stage === 'new_lead' ? 'first_contact' :
                       stage === 'contacted' ? 'follow_up' :
                       stage === 'qualified' ? 'send_proposal' :
                       stage === 'proposal_sent' ? 'check_decision' :
                       'negotiate'
      }
    });
  }
}

return staleLeads.length > 0 ? staleLeads : [{ json: { no_stale: true } }];
